INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(43711, 'Songofsongs 3:7', 'Songofsongs', 3, 7, 'دا د سليمان ګاډۍ ده وګورئينه، چې ورسره شپېتۀ تکړه کسان په پرګله کښې راروان دينه، د بنى اِسرائيلو د ټولو نه ښۀ فوجيان ورسره دينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs3_verse_7.mp3', '', 1761754199, 1761754199),
(43712, 'Songofsongs 3:8', 'Songofsongs', 3, 8, 'هغوئ ټول په تُورو باندې سمبال دينه، او په جنګ کښې هم ماهر دينه، هر يو سره په ترخ کښې تُوره ده، او هغوئ په شپه کښې د بادشاه د حفاظت کولو جوګه هم دينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs3_verse_8.mp3', '', 1761754199, 1761754199),
(43713, 'Songofsongs 3:9', 'Songofsongs', 3, 9, 'سليمان بادشاه شاهى ګاډۍ ځان دپاره د لبنان د دِيار د لرګو نه جوړه کړې ده نه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs3_verse_9.mp3', '', 1761754199, 1761754199),
(43714, 'Songofsongs 3:10', 'Songofsongs', 3, 10, 'د هغې ستنې هغۀ د سپينو زرو نه جوړې کړې دينه، او د هغې چت يې د سرو زرو نه جوړ کړے دېنه، او د هغې بالښتونه کاسنى دينه. هغه د يروشلم د پېغلو په مينې سره ښائسته شوې وه نه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs3_verse_10.mp3', '', 1761754199, 1761754199),
(43715, 'Songofsongs 3:11', 'Songofsongs', 3, 11, 'اے د يروشلم پېغلو راشئ کنه، او سليمان بادشاه وګورئينه هغۀ هغه تاج په سر کړے دېنه کوم چې د وادۀ په ورځ مور ورکړے وونه، ډېره د خوشحالۍ ورځ وه د هغۀ د ټولو نه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs3_verse_11.mp3', '', 1761754199, 1761754199),
(43716, 'Isaiah 20:1', 'Isaiah', 20, 1, 'د اشور پاچا سرجون په حکم، د هغه د لښکر قوماندان د فلسطین د اشدود په ښار باندې حمله وکړه او هغه یې ونیوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah20_verse_1.mp3', '', 1761754199, 1761754199),
(43717, 'Isaiah 20:2', 'Isaiah', 20, 2, 'په هغه وخت کې څښتن د آموص زوی اشعیا ته ویلي وو چې خپل د ویر کالي او خپلې څپلۍ وباسي. هغه دا ومنله، بیا هغه لوڅ ځان او لوڅې پښې روان شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah20_verse_2.mp3', '', 1761754199, 1761754199),
(43718, 'Isaiah 20:3', 'Isaiah', 20, 3, 'نو څښتن وویل: «زما خدمتګار اشعیا درې کاله لوڅ ځان او لوڅې پښې ګرځېدلی دی. دا د هغې نښه ده چې د مصر او ایتوپیا خلک به په لویه بلا اخته شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah20_verse_3.mp3', '', 1761754199, 1761754199),
(43719, 'Isaiah 20:4', 'Isaiah', 20, 4, 'په دې ډول به د اشور پاچا د مصر او ایتوپیا خلک د اسیرانو په توګه ونیسي. ځوانان او زاړه به یې په لوڅ ځان او لوڅې پښې روان شي. د هغوی هرڅه به بربنډ وي او دا به د مصر دپاره د شرم خبره وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah20_verse_4.mp3', '', 1761754199, 1761754199),
(43720, 'Isaiah 20:5', 'Isaiah', 20, 5, 'هغو خلکو چې په ایتوپیا باندې تکیه کوله او په مصر یې ویاړ کاوه، هغوی به ناامیده او رسوا شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah20_verse_5.mp3', '', 1761754199, 1761754199),
(43721, 'Isaiah 20:6', 'Isaiah', 20, 6, 'هغه وخت به د فلسطین د ساحل اوسېدونکي ووایي: ‹وګورئ، په هغو خلکو چې مونږ ورباندې تکیه کوله او مونږ ورنه د مرستې تمه لرله چې مونږ به د اشور پاچا له حملې څخه وساتي، داسې بلا راغله، نو مونږ به څنګه ژوندي پاتې شو؟›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah20_verse_6.mp3', '', 1761754199, 1761754199),
(43722, 'Genesis 22:1', 'Genesis', 22, 1, 'څه موده وروسته خدای په ابراهیم باندې ازمېښت وکړ او هغه ته یې وویل: «ای ابراهیمه!» او ابراهیم ځواب ورکړ: «هو، زه حاضر یم!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_1.mp3', '', 1761754199, 1761754199),
(43723, 'Genesis 22:2', 'Genesis', 22, 2, 'خدای وویل: «خپل زوی اسحاق چې ستا یوازېنی زوی دی او په تا باندې ډېر ګران دی، واخله او د موریا سیمې ته لاړ شه او هغه په هغه غره باندې چې زه یې درته ښایم زما دپاره د سوځېدونکې نذرانې په توګه قرباني کړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_2.mp3', '', 1761754199, 1761754199),
(43724, 'Genesis 22:3', 'Genesis', 22, 3, 'ابراهیم سهار وختي پاڅېد، د سوځېدونکې نذرانې دپاره یې لرګي مات کړل او هغه یې په خره باندې بار کړل. خپل دوه نوکران او خپل زوی اسحاق یې د ځان سره واخیستل او هغه ځای ته روان شول چې خدای ورته ویلي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_3.mp3', '', 1761754199, 1761754199),
(43725, 'Genesis 22:4', 'Genesis', 22, 4, 'په درېمه ورځ ابراهیم هغه ځای د لېرې څخه ولیده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_4.mp3', '', 1761754199, 1761754199),
(43726, 'Genesis 22:5', 'Genesis', 22, 5, 'بیا هغه خپلو نوکرانو ته وویل: «تاسو دلته د خره سره پاتې شئ، زه او هلک به هلته لاړ شو. مونږ به هلته عبادت وکړو او بېرته به بیا تاسو ته راشو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_5.mp3', '', 1761754199, 1761754199),
(43727, 'Genesis 22:6', 'Genesis', 22, 6, 'ابراهیم د قربانۍ لرګي خپل زوی ته په اوږو باندې کېښودل او خپله یې چاړه او د اور بلولو دپاره یې سکاره واخیستل او دواړه یوځای سره روان شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_6.mp3', '', 1761754199, 1761754199),
(43728, 'Genesis 22:7', 'Genesis', 22, 7, 'اسحاق خپل پلار ته وویل: «ای پلاره!» هغه ځواب ورکړ: «وایه زما زویه!» هغه وویل: «زه پوهېږم چې ستا سره اور او لرګي شته، خو د سوځېدونکې نذرانې دپاره وری چېرته دی؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_7.mp3', '', 1761754199, 1761754199),
(43729, 'Genesis 22:8', 'Genesis', 22, 8, 'ابراهیم ځواب ورکړ: «ای زما زویه، خدای به په خپله د سوځېدونکې نذرانې دپاره وری تیار کړي.» او دواړه یوځای سره روان شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_8.mp3', '', 1761754199, 1761754199),
(43730, 'Genesis 22:9', 'Genesis', 22, 9, 'کله چې هغه ځای ته چې خدای ورته ویلي وو ورسېدل، ابراهیم هلته د قربانۍ ځای جوړ کړ او په هغه باندې یې لرګي په ترتیب سره کېښودل. هغه خپل زوی اسحاق وتاړه او د لرګیو دپاسه یې څملاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_9.mp3', '', 1761754199, 1761754199),
(43731, 'Genesis 22:10', 'Genesis', 22, 10, 'بیا هغه چاړه راواخیستله چې خپل زوی حلال کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_10.mp3', '', 1761754199, 1761754199),
(43732, 'Genesis 22:11', 'Genesis', 22, 11, 'خو د څښتن فرښتې د اسمان څخه هغه ته غږ وکړ: «ای ابراهیمه، ای ابراهیمه!» هغه ځواب ورکړ: «زه حاضر یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_11.mp3', '', 1761754199, 1761754199),
(43733, 'Genesis 22:12', 'Genesis', 22, 12, 'هغه وویل: «هلک ژوبل نه کړې او په هغه باندې هېڅ ونه کړې! زه اوس پوه شوم چې ته د خدای څخه وېرېږې، ځکه چې خپل یوازېنی زوی دې زما څخه درېغ نه کړ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_12.mp3', '', 1761754199, 1761754199),
(43734, 'Genesis 22:13', 'Genesis', 22, 13, 'ابراهیم سترګې پورته کړې او ویې لیدل چې شاته یې یو پسه دی چې ښکرونه یې په بوټي کې نښتي وو. ابراهیم ورغی، هغه یې راونیوه او د خپل زوی په ځای یې د سوځېدونکې نذرانې په توګه قرباني کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_13.mp3', '', 1761754199, 1761754199),
(43735, 'Genesis 22:14', 'Genesis', 22, 14, 'ابراهیم دغه ځای د «څښتن به یې تیاروي» په نوم یاد کړ او حتی تر نن ورځې پورې داسې ویل کیږي: «هغه به د څښتن په غره کې تیار شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_14.mp3', '', 1761754199, 1761754199),
(43736, 'Genesis 22:15', 'Genesis', 22, 15, 'د څښتن فرښتې د دوهم ځل دپاره د اسمان څخه په ابراهیم باندې غږ وکړ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_15.mp3', '', 1761754199, 1761754199),
(43737, 'Genesis 22:16', 'Genesis', 22, 16, 'او ویې ویل: «څښتن داسې وایي: په دې خاطر چې تا دا کار وکړ او خپل یوازېنی زوی دې زما څخه درېغ نه کړ، زه په خپل ذات باندې قسم خورم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_16.mp3', '', 1761754199, 1761754199),
(43738, 'Genesis 22:17', 'Genesis', 22, 17, 'زه به په رښتیا سره برکت درکړم او ستا نسل به لکه د اسمان د ستورو او هغو شګو په شان چې د بحیرې په غاړه پرتې دي، زیات کړم. هغوی به خپلو دښمنانو ته ماتې ورکړي او د هغوی ښارونه به ونیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_17.mp3', '', 1761754199, 1761754199),
(43739, 'Genesis 22:18', 'Genesis', 22, 18, 'د ځمکې ټول قومونه به ستا د اولادې په وسیله برکت ومومي، ځکه چې تا زما حکم منلی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_18.mp3', '', 1761754199, 1761754199),
(43740, 'Genesis 22:19', 'Genesis', 22, 19, 'نو ابراهیم بېرته خپلو نوکرانو ته راستون شو او هغوی ټول یوځای بیرشبع ته لاړل او ابراهیم په بیرشبع کې پاتې شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_19.mp3', '', 1761754199, 1761754199),
(43741, 'Genesis 22:20', 'Genesis', 22, 20, 'څه موده وروسته ابراهیم خبر شو چې د ده د ورور ناحور ښځه میلکه هم مور شوه او زامن یې زېږولي دي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_20.mp3', '', 1761754199, 1761754199),
(43742, 'Genesis 22:21', 'Genesis', 22, 21, 'د هغه لومړنی اولاد عوص، د هغه ورور بوز، قموییل د آرام پلار،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_21.mp3', '', 1761754199, 1761754199),
(43743, 'Genesis 22:22', 'Genesis', 22, 22, 'او د هغې نور پنځه زامن دا وو: کاسد، حزو، فلداش، یدلاف او بتوییل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_22.mp3', '', 1761754199, 1761754199),
(43744, 'Genesis 22:23', 'Genesis', 22, 23, 'د بتوییل څخه ربکا پیدا شوه. میلکې د ابراهیم ورور ناحور ته دا اته زامن وزېږول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_23.mp3', '', 1761754199, 1761754199),
(43745, 'Genesis 22:24', 'Genesis', 22, 24, 'ریومه د ناحور وینځې هم طابح، جاحم، تاحش او معکه وزېږول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis22_verse_24.mp3', '', 1761754199, 1761754199),
(43746, 'Genesis 15:1', 'Genesis', 15, 1, 'څه موده وروسته څښتن په رویا کې ابرام ته وویل: «ای ابرامه مه وېرېږه، زه ستا سپر یم او ډېر لوی اجر به درکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis15_verse_1.mp3', '', 1761754199, 1761754199),
(43747, 'Genesis 15:2', 'Genesis', 15, 2, 'ابرام وویل: «ای څښتن تعالی، ماته به څه راکړې، ځکه چې زه بې‌اولاده پاتې شوم. زما یوازېنی وارث دمشقي الیعازر دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis15_verse_2.mp3', '', 1761754199, 1761754199),
(43748, 'Genesis 15:3', 'Genesis', 15, 3, 'ماته دې اولادونه نه دي راکړي، نو زما د کورنۍ نوکر به زما میراث خور شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis15_verse_3.mp3', '', 1761754199, 1761754199),
(43749, 'Genesis 15:4', 'Genesis', 15, 4, 'څښتن په ځواب کې وویل: «دا سړی به ستا میراث خور نه وي، بلکې ستا خپل زوی چې په خپله ستا څخه به پیدا شي، ستا میراث خور وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis15_verse_4.mp3', '', 1761754199, 1761754199),
(43750, 'Genesis 15:5', 'Genesis', 15, 5, 'څښتن هغه دباندې وویست او ورته ویې ویل: «اسمان ته وګوره او هڅه وکړه چې ستوري وشمارې، نو ستا اولاده به د هغو په شان دومره زیاته وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis15_verse_5.mp3', '', 1761754199, 1761754199),
(43751, 'Genesis 15:6', 'Genesis', 15, 6, 'ابرام په څښتن باندې ایمان راوړ او د هغه ایمان له امله څښتن هغه عادل وګاڼه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis15_verse_6.mp3', '', 1761754199, 1761754199),
(43752, 'Genesis 15:7', 'Genesis', 15, 7, 'بیا څښتن هغه ته وویل: «زه هغه څښتن یم چې ته مې د کلدانیانو د اور د ښار څخه راوویستلې چې دا ځمکه درکړم او ستا ملکیت شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis15_verse_7.mp3', '', 1761754199, 1761754199),
(43753, 'Genesis 15:8', 'Genesis', 15, 8, 'خو ابرام وویل: «ای څښتن تعالی، زه به څنګه پوه شم چې هغه به زما شي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis15_verse_8.mp3', '', 1761754199, 1761754199),
(43754, 'Genesis 15:9', 'Genesis', 15, 9, 'نو څښتن هغه ته وویل: «ماته یوه درې کلنه غوا، درې کلنه وزه، درې کلن پسه، یوه کوتره او یوه قمري راوړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis15_verse_9.mp3', '', 1761754199, 1761754199),
(43755, 'Genesis 15:10', 'Genesis', 15, 10, 'ابرام دا ټول هغه ته راوړل او هر یو یې په منځ کې دوه ټوټې کړ او هره نیمه شوې ټوټه یې بلې ټوټې ته مخامخ کېښودله، خو مرغان یې دوه ټوټې نه کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis15_verse_10.mp3', '', 1761754199, 1761754199),
(43756, 'Genesis 15:11', 'Genesis', 15, 11, 'کله چې ټپوسان د دې مړو حیواناتو په تنو باندې راښکته شول، ابرام هغه وشړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis15_verse_11.mp3', '', 1761754199, 1761754199),
(43757, 'Genesis 15:12', 'Genesis', 15, 12, 'کله چې لمر په پرېوتلو شو، په ابرام باندې ډېر دروند خوب راغی او سخته وېروونکې تیاره ورباندې راغله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis15_verse_12.mp3', '', 1761754199, 1761754199),
(43758, 'Genesis 15:13', 'Genesis', 15, 13, 'څښتن هغه ته وویل: «په دې پوه شه چې ستا اولاده به په پردۍ خاوره کې مسافره شي او هغوی به هلته غلامان شي او په دوی باندې به څلور سوه کاله ظلم کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis15_verse_13.mp3', '', 1761754199, 1761754199),
(43759, 'Genesis 15:14', 'Genesis', 15, 14, 'خو زه به هغه قوم ته چې دوی یې غلامي کوي، سزا ورکړم او له هغې وروسته به دوی د ډېرې شتمنۍ سره ووځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis15_verse_14.mp3', '', 1761754199, 1761754199),
(43760, 'Genesis 15:15', 'Genesis', 15, 15, 'ته به په پاخه عمر کې په ارامۍ سره مړ شې او ښخ به شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis15_verse_15.mp3', '', 1761754199, 1761754199),
(43761, 'Genesis 15:16', 'Genesis', 15, 16, 'ستا اولاده به له څلورم نسل څخه وروسته بېرته دلته راشي، ځکه زه به تر هغې پورې اموریان ونه شړم، ترڅو پورې چې هغوی دومره بدکاره شي چې باید سزا ومومي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis15_verse_16.mp3', '', 1761754199, 1761754199),
(43762, 'Genesis 15:17', 'Genesis', 15, 17, 'کله چې لمر پرېوت او تیاره شوه، د لوګي څخه ډک یو تنور او بلېدونکی څراغ راښکاره شول او د دې ټوټو له منځ څخه تېر شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis15_verse_17.mp3', '', 1761754199, 1761754199),
(43763, 'Genesis 15:18', 'Genesis', 15, 18, 'په هماغه ورځ څښتن د ابرام سره لوظ وکړ او ویې ویل: «زه ستا اولادې ته دا ټوله خاوره د مصر د سیند څخه نیولې د فرات تر لوی سیند پورې ورکوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis15_verse_18.mp3', '', 1761754199, 1761754199),
(43764, 'Genesis 15:19', 'Genesis', 15, 19, 'یعنې د قینیانو، قنزیانو، قدمونیانو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis15_verse_19.mp3', '', 1761754199, 1761754199),
(43765, 'Genesis 15:20', 'Genesis', 15, 20, 'حیتیانو، فرزیانو، رفاییانو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis15_verse_20.mp3', '', 1761754199, 1761754199),
(43766, 'Genesis 15:21', 'Genesis', 15, 21, 'اموریانو، کنعانیانو، جرجاشیانو او یبوسیانو خاوره.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis15_verse_21.mp3', '', 1761754199, 1761754199),
(43767, 'Job 10:1', 'Job', 10, 1, 'زۀ د خپل ژوند نه نفرت کوم، زۀ به ډېر شکايتونه کوم، زۀ به په مايوسۍ کښې خبرې کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job10_verse_1.mp3', '', 1761754199, 1761754199),
(43768, 'Job 10:2', 'Job', 10, 2, 'زۀ به خُدائ پاک ته ووايم چې ما مۀ رد کوه، او تۀ چې په ما کوم اِلزام لګوې نو د هغې نه ما خبر کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job10_verse_2.mp3', '', 1761754199, 1761754199),
(43769, 'Job 10:3', 'Job', 10, 3, 'دا تا ته ښۀ ښکارى، چې ما په عذاب کړې، چې ما يعنې د خپلو لاسونو کار رد کړې او د بدکارو خلقو منصوبو ته ښۀ ووائې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job10_verse_3.mp3', '', 1761754199, 1761754199),
(43770, 'Job 10:4', 'Job', 10, 4, 'ولې ستا نظر د انسانانو په شان دے؟ تۀ د انسان په شان کتل کوې څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job10_verse_4.mp3', '', 1761754199, 1761754199),
(43771, 'Job 10:5', 'Job', 10, 5, 'ستا عُمر زمونږ په شان لنډ دے څۀ؟ يا ستا کالونه د انسانانو د کالونو په شان دى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job10_verse_5.mp3', '', 1761754199, 1761754199),
(43772, 'Job 10:6', 'Job', 10, 6, 'چې تۀ زما غلطى معلوموې او زما ګناه لټوې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job10_verse_6.mp3', '', 1761754199, 1761754199),
(43773, 'Job 10:7', 'Job', 10, 7, 'اګر چې تا ته پته ده چې زۀ بې‌ګناه يم، او ستا د لاسونو نه مې هيڅ څوک نۀ شى بچ کولے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job10_verse_7.mp3', '', 1761754199, 1761754199),
(43774, 'Job 10:8', 'Job', 10, 8, 'ستا لاسونو ما له صورت راکړو او جوړ يې کړم، او اوس مې بېخى تباه کوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job10_verse_8.mp3', '', 1761754199, 1761754199),
(43775, 'Job 10:9', 'Job', 10, 9, 'هغه راپه ياد کړه چې تا زۀ د خټو نه جوړ کړم، او اوس به تۀ ما بيا خاورې کوې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job10_verse_9.mp3', '', 1761754199, 1761754199),
(43776, 'Job 10:10', 'Job', 10, 10, 'تا زۀ د مور په خېټه کړم او زما وجود دې جوړ کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job10_verse_10.mp3', '', 1761754199, 1761754199),
(43777, 'Job 10:11', 'Job', 10, 11, 'تا زۀ د غوښې او څرمنې نه جوړ کړم، او د هډُوکو او پټو په ذريعه دې يو ځائ وتړلم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job10_verse_11.mp3', '', 1761754199, 1761754199),
(43778, 'Job 10:12', 'Job', 10, 12, 'تا ما له ژوند او نۀ ختمېدونکې مينه راکړې ده، او تا زما د ژوند ښۀ حِفاظت کړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job10_verse_12.mp3', '', 1761754199, 1761754199),
(43779, 'Job 10:13', 'Job', 10, 13, 'خو اوس ما ته پته ولګېده چې تا د ډېر وخت نه ما ته د نقصان دپاره پټه منصوبه جوړه کړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job10_verse_13.mp3', '', 1761754199, 1761754199),
(43780, 'Job 10:14', 'Job', 10, 14, 'کۀ زۀ ګناه وکړم نو تۀ ما وينې، او زما ګناه تۀ نۀ معاف کوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job10_verse_14.mp3', '', 1761754199, 1761754199),
(43781, 'Job 10:15', 'Job', 10, 15, 'کۀ زۀ بدکاره يم، نو ما غمژن کړه. او کۀ زۀ صادق يم، نو خپل سر نۀ شم اوچتولے، ځکه چې زۀ د شرم سره مخ شوے يم او په غمونو کښې ډوب يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job10_verse_15.mp3', '', 1761754199, 1761754199),
(43782, 'Job 10:16', 'Job', 10, 16, 'او کۀ زۀ خپل سر اوچتوم، نو تۀ د ازمرى په شان زما ښکار کوې، او خپل لوئ طاقت زما خِلاف استعمالوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job10_verse_16.mp3', '', 1761754199, 1761754199),
(43783, 'Job 10:17', 'Job', 10, 17, 'تۀ خپل ګواهان زما خِلاف بيا راتازه کړې، او خپله غصه زما خِلاف زياتوې، تۀ زما خِلاف تازه دم فوجيان رالېږې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job10_verse_17.mp3', '', 1761754199, 1761754199),
(43784, 'Job 10:18', 'Job', 10, 18, 'تا زۀ د مور د خېټې نه ولې راوويستلم؟ کاش چې زۀ د خلقو د سترګو د ليدو نه مخکښې مړ شوے وے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job10_verse_18.mp3', '', 1761754199, 1761754199),
(43785, 'Job 10:19', 'Job', 10, 19, 'ښۀ به دا وے چې د سره پېدا شوے نۀ وے او د مور د خېټې نه سيدها قبر ته تلے وے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job10_verse_19.mp3', '', 1761754199, 1761754199),
(43786, 'Job 10:20', 'Job', 10, 20, 'زما ژوند لنډ نۀ دے څۀ؟ ما پرېږده نو چې داسې يو ساعت په آرام شم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job10_verse_20.mp3', '', 1761754199, 1761754199),
(43787, 'Job 10:21', 'Job', 10, 21, 'خو چې زۀ لاړ شم او بيا هيڅکله راواپس نۀ شم، چې تور او د تکې تورې تيارې مُلک ته لاړ شم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job10_verse_21.mp3', '', 1761754199, 1761754199),
(43788, 'Job 10:22', 'Job', 10, 22, 'د نيمې شپې په شان تيارۀ، د لانجو مُلک ته، چرته چې رڼا هم د تيارې په شان وى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job10_verse_22.mp3', '', 1761754199, 1761754199),
(43789, 'Psalms 88:1', 'Psalms', 88, 1, 'ای څښتن خدایه خلاصوونکیه زما ټوله ورځ تاته زاري کړم د شپې ستا حضور ته ژاړم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms88_verse_1.mp3', '', 1761754199, 1761754199),
(43790, 'Psalms 88:2', 'Psalms', 88, 2, 'کړه قبوله زما دعا غوږ مې ونیسه زاریو ته!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms88_verse_2.mp3', '', 1761754199, 1761754199),
(43791, 'Psalms 88:3', 'Psalms', 88, 3, 'ډېر تکلیفونه دي راغلي په ما زه یم ګور ته نژدې شوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms88_verse_3.mp3', '', 1761754199, 1761754199),
(43792, 'Psalms 88:4', 'Psalms', 88, 4, 'خلک وایي راته داسې یې ولاړ د ګور په غاړه او زه یم کمزوری شوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms88_verse_4.mp3', '', 1761754199, 1761754199),
(43793, 'Psalms 88:5', 'Psalms', 88, 5, 'زه په مړو کې حساب یم د وژل شویو په شان چې وي پراته قبر کې لکه هغوی چې تا هېر کړي او نور ورسره نه کړې مرسته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms88_verse_5.mp3', '', 1761754199, 1761754199),
(43794, 'Psalms 88:6', 'Psalms', 88, 6, 'زه دې په کنده کې د قبر غورځولی یمه تورې تیارې او ژور ځای کې اچولی یمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms88_verse_6.mp3', '', 1761754199, 1761754199),
(43795, 'Psalms 88:7', 'Psalms', 88, 7, 'دا ستا غضب راباندې دروند پروت دی ټولو څپو ستا لاندې کړی یمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms88_verse_7.mp3', '', 1761754199, 1761754199),
(43796, 'Psalms 88:8', 'Psalms', 88, 8, 'زما نه لېرې کړل دوستان دې زما د کرکې وړ دې کړم نظر کې د دوی داسې راګېر یم چې د تېښتې لاره نه لرمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms88_verse_8.mp3', '', 1761754199, 1761754199),
(43797, 'Psalms 88:9', 'Psalms', 88, 9, 'کمزورې شوې مې دي سترګې له ډېره غمه څخه څښتنه هره ورځ زاري کړم تاته پورته کوم درته لاسونه د دعا دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms88_verse_9.mp3', '', 1761754199, 1761754199),
(43798, 'Psalms 88:10', 'Psalms', 88, 10, 'ایا ته کړې معجزې مړو دپاره؟ ایا مړي پورته کیږي ستا ثنا ته؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms88_verse_10.mp3', '', 1761754199, 1761754199),
(43799, 'Psalms 88:11', 'Psalms', 88, 11, 'ایا په قبر کې کېدای شي بیان ستا د تلپاتې مینې؟ او یا بیان ستا د وفا د تباهۍ کنده کې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms88_verse_11.mp3', '', 1761754199, 1761754199),
(43800, 'Psalms 88:12', 'Psalms', 88, 12, 'ایا ښکاریږي معجزې دې په تیاره مکان کې او یا ستا نېکي د هېرېدو په ځای کې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms88_verse_12.mp3', '', 1761754199, 1761754199),
(43801, 'Psalms 88:13', 'Psalms', 88, 13, 'خو ای څښتنه، کړم زاري د مرستې تاته او هر سهار دعا ستا حضور ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms88_verse_13.mp3', '', 1761754199, 1761754199),
(43802, 'Psalms 88:14', 'Psalms', 88, 14, 'ما ردوې ولې څښتنه؟ زما نه ولې پټوې خپل مخ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms88_verse_14.mp3', '', 1761754199, 1761754199),
(43803, 'Psalms 88:15', 'Psalms', 88, 15, 'له هغه وخته چې لا ځوان ومه زه ومه اخته په کړاوونو او نژدې وم مرګ ته په سبب دې د کارونو وېروونکو زه بې‌وسه یمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms88_verse_15.mp3', '', 1761754199, 1761754199),
(43804, 'Psalms 88:16', 'Psalms', 88, 16, 'سخت غضب دې کړمه غرق ستا بریدونو وېروونکو تباه کړی یمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms88_verse_16.mp3', '', 1761754199, 1761754199),
(43805, 'Psalms 88:17', 'Psalms', 88, 17, 'لکه سېلاب په شان راتاو وي رانه ټوله ورځ راګېروي مې د هر لوري څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms88_verse_17.mp3', '', 1761754199, 1761754199),
(43806, 'Psalms 88:18', 'Psalms', 88, 18, 'راڅخه لېرې دې خپلوان او هم دوستان کړل زما یوازې مل ده راسره تیاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms88_verse_18.mp3', '', 1761754199, 1761754199),
(43807, 'Esther 4:1', 'Esther', 4, 1, 'کله چې مردخای د هغو ټولو کارونو څخه چې شوي وو خبر شو، هغه له خفګانه خپل کالي وشکول، د ویر کالي یې واغوستل او ایرې یې په سر باندې واچولې. بیا هغه ښار ته ووت او په لوړ اواز یې سخت ژړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther4_verse_1.mp3', '', 1761754199, 1761754199),
(43808, 'Esther 4:2', 'Esther', 4, 2, 'هغه د ماڼۍ تر دروازې پورې ورسېده. خو دننه لاړ نه شو، ځکه هېچا ته اجازه نه وه چې د ویر د کالیو سره ماڼۍ ته ننوځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther4_verse_2.mp3', '', 1761754199, 1761754199),
(43809, 'Esther 4:3', 'Esther', 4, 3, 'هر ولایت ته چې به د پاچا فرمان او حکم رسېده هلته به د یهودیانو په منځ کې لوی ویر ؤ، هغوی به روژه نیوله، ژړا او ویر به یې کاوه. ډېر به د ویر په کالیو کې په ایرو باندې ناست وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther4_verse_3.mp3', '', 1761754199, 1761754199),
(43810, 'Esther 4:4', 'Esther', 4, 4, 'کله چې د استر وینځې او خصیان راغلل او د مردخای په هکله یې هغې ته خبر ورکړ، نو ملکه ډېره خفه شوه. هغه ته یې کالي ورولېږل چې د ویر د کالیو په ځای یې واغوندي، خو هغه ونه منل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther4_verse_4.mp3', '', 1761754199, 1761754199);